public static void versionIncrement(RecId _oldId, RecId _newId)
{
    TFMConditionsParameters     cpTbl;
    TFMConditionsLink           links, newLinks;
    RecId                       oldRecId;
    Map                         recIdTranslator=new Map(Types::Int64, Types::Int64);
    MapEnumerator               mEnum;
    while select cpTbl where cpTbl.ConditionsKey == _oldId
    {
        oldRecId = cpTbl.recId;
        cpTbl.ConditionsKey = _newID;
        cpTbl.insert();
        TFMConditionsParameterValues::versionIncrement(oldRecId, cpTbl.recid);
        recIdTranslator.insert(oldRecId, cpTbl.RecId);
    }

    mEnum = recIdTranslator.getEnumerator();

    while (mEnum.moveNext())
    {
        oldRecId = mEnum.currentKey();
        while select links where links.FromCondition == oldRecId
        {
            newLinks.FromCondition  = recIdTranslator.lookup(oldRecId);
            newLinks.ToCondition    = recIdTranslator.lookup(links.ToCondition);
            newLinks.insert();
        }
    }

}
